@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

<span class="badge bg-primary fs-5 mb-3">@_notifications.Count</span>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var notification in _notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item">
                <strong>@notification.Message</strong>
                <br />
                <small class="text-muted">@notification.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorApp.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        // Load initial data during server-side prerender AND interactive init.
        // This ensures the SSR HTML already contains the notifications.
        _notifications = NotificationService.GetAll();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires when the component is truly interactive
            // (not during static SSR), so the polling loop starts only once live.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(5000, cancellationToken).ConfigureAwait(false);

            // Simulate a new notification arriving on the server side
            NotificationService.SimulateIncoming();

            // Fetch only notifications newer than our latest
            var latest = _notifications.Count > 0
                ? _notifications.Max(n => n.Timestamp)
                : DateTime.MinValue;

            var newOnes = NotificationService.GetSince(latest);

            if (newOnes.Count > 0)
            {
                _notifications.AddRange(newOnes);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

